const propertyRecordMatches = (
  result: Effect.Success<ReturnType<typeof executePropertyRecords>>,
  ref: ContextRef,
  tenantId: string,
) =>
  [
    ...result.properties.map(({ propertyRef }) => propertyRef),
    ...result.units.map(({ unitRef }) => unitRef),
    ...result.assets.map(({ assetRef }) => assetRef),
  ].some(
    (owned) =>
      owned.resourceId === ref.resourceId && owned.tenantId === tenantId && owned.resourceType === ref.resourceType,
  );

const propertyReadFailure = (error: Effect.Error<ReturnType<typeof executePropertyRecords>>) =>
  Match.value(error).pipe(
    Match.tag(
      'RecordsForbiddenProblem',
      'RecordsNotFoundProblem',
      () =>
        new WorkReferenceIneligible({
          code: 'work_reference_ineligible',
          reason: 'Task context is absent or forbidden',
        }),
    ),
    Match.orElse(referenceUnavailable),
  );

